using IndieRun;
using System.ComponentModel;
using System.Text.Json;
using System.Security.Cryptography;

static void Check(bool value,string message){if(!value)throw new Exception(message);}
static void Refuse(Action action){try{action();}catch(Exception ex)when(ex is IOException or UnauthorizedAccessException or InvalidDataException){return;}throw new Exception("Expected refusal");}
static T Copy<T>(T value)=>JsonSerializer.Deserialize<T>(JsonSerializer.Serialize(value))!;
if(args[0]=="--probe"){File.WriteAllText(args[1],Environment.CurrentDirectory);return;}
var run=Path.Combine(Path.GetFullPath(args[0]),"run-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(run);var results=new List<object>();int failed=0;
async Task Test(string name,Func<string,Task> action)
{var root=Path.Combine(run,name);Directory.CreateDirectory(root);try{await action(root);results.Add(new{name,status="PASS"});Console.WriteLine("PASS: "+name);}catch(Exception ex){failed++;results.Add(new{name,status="FAIL",error=ex.ToString()});Console.WriteLine("FAIL: "+name+" · "+ex.Message);}}
Task Done()=>Task.CompletedTask;
(WorkspaceDocument Plan,PlayerDocument Play,LibraryDocument Library) Fixture(string root,bool registered=false)
{
    var path=Path.Combine(root,"source");Directory.CreateDirectory(path);File.WriteAllBytes(Path.Combine(path,"Game.exe"),[1,2,3]);
    var p=new Package {IsReal=true,Id=Guid.NewGuid().ToString("N"),Source=path,DetectedRoot=path,SearchRoot=root,Name="Game",Folder="source",Alias="내 게임",Genres=["퍼즐"]};
    var plan=new WorkspaceDocument {SearchRoot=root,Destination=Path.Combine(root,"library"),Packages=[p],Checkpoints=[WorkspaceReconciler.Capture(p,GameScanner.Scan(path))]};
    var lib=new LibraryDocument();if(registered){lib=new LibraryStore(plan.Destination).Register(p,[],GameScanner.Scan(path)).Document;plan.Checkpoints=[WorkspaceReconciler.Capture(p,GameScanner.Scan(path))];}
    return (plan,new PlayerDocument {Games=[new GamePlay {Id=p.Id,Executable="Game.exe",Favorite=true,Arguments="--arg",Image=".indierun-art/pic.png"}]},lib);
}
WorkspaceDocument Relink(WorkspaceDocument plan,PlayerDocument play,LibraryDocument lib,string folder)=>ReconnectPlanner.Prepare(plan,plan.Packages[0].Id,folder,GameScanner.Scan(folder),lib,play);
await Test("ready-and-first-executable-selection",root=>{var (plan,play,_)=Fixture(root);var p=plan.Packages[0];Check(GameLaunch.Inspect(p,play.Games[0]).Problem==LaunchProblem.None,"Ready");play.Games[0].Executable="";Check(GameLaunch.Inspect(p,play.Games[0]).Problem==LaunchProblem.Setup,"Setup");return Done();});
await Test("live-folder-missing-before-scan",root=>{var (plan,play,_)=Fixture(root);Directory.Move(plan.Packages[0].Source,Path.Combine(root,"moved"));Check(GameLaunch.Inspect(plan.Packages[0],play.Games[0]).Problem==LaunchProblem.FolderMissing,"Folder");return Done();});
await Test("executable-and-working-folder-distinguished",root=>{var (plan,play,_)=Fixture(root);var g=play.Games[0];g.Executable="gone.exe";Check(GameLaunch.Inspect(plan.Packages[0],g).Problem==LaunchProblem.ExecutableMissing,"Exe");g.Executable="Game.exe";g.WorkingDirectory="gone";Check(GameLaunch.Inspect(plan.Packages[0],g).Problem==LaunchProblem.WorkingFolderMissing,"Workdir");return Done();});
await Test("mismatched-and-missing-registered-id",root=>{var (plan,play,_)=Fixture(root);var p=plan.Packages[0];Check(GameLaunch.Inspect(p,play.Games[0],true).Problem==LaunchProblem.Identity,"Missing ID");LibraryStore.EnsureIdentity(p.Source,Guid.NewGuid().ToString("N"));Check(GameLaunch.Inspect(p,play.Games[0]).Problem==LaunchProblem.Identity,"Mismatched ID");return Done();});
await Test("locked-id-file-reports-access",root=>{var (plan,play,_)=Fixture(root,true);using var held=new FileStream(Path.Combine(plan.Packages[0].Source,LibraryStore.MarkerName),FileMode.Open,FileAccess.ReadWrite,FileShare.None);Check(GameLaunch.Inspect(plan.Packages[0],play.Games[0],true).Problem==LaunchProblem.Access,"Lock misclassified");return Done();});
await Test("corrupt-id-reports-identity-not-launch-settings",root=>{var (plan,play,_)=Fixture(root);File.WriteAllText(Path.Combine(plan.Packages[0].Source,LibraryStore.MarkerName),"{broken");Check(GameLaunch.Inspect(plan.Packages[0],play.Games[0]).Problem==LaunchProblem.Identity,"Corrupt ID misclassified");return Done();});
await Test("native-process-errors-classified",root=>{foreach(var code in new[]{5,32,740})Check(GameLaunch.Classify(new Win32Exception(code)).Problem==LaunchProblem.Access,"Access "+code);Check(GameLaunch.Classify(new Win32Exception(193)).Problem==LaunchProblem.InvalidProgram,"Invalid exe");Check(GameLaunch.Classify(new Win32Exception(267)).Problem==LaunchProblem.WorkingFolderMissing,"Invalid workdir");Check(GameLaunch.Classify(new Win32Exception(999)).Problem==LaunchProblem.Failed,"Unknown");return Done();});
await Test("actual-invalid-executable-start-failure",root=>{var (plan,play,_)=Fixture(root);try{using var process=PlayerStore.Launch(plan.Packages[0],play.Games[0]);throw new Exception("Unexpected start");}catch(Win32Exception ex){Check(GameLaunch.Classify(ex).Problem==LaunchProblem.InvalidProgram,"Bad exe classified incorrectly");}Check(play.Games[0].LastPlayedUtc==null,"Failed launch updated recent");return Done();});
await Test("reconnect-preview-is-pure-and-preserves-settings",root=>{var (plan,play,lib)=Fixture(root,true);var before=JsonSerializer.Serialize(plan);var settings=JsonSerializer.Serialize(play);var folder=Path.Combine(root,"renamed");Directory.Move(plan.Packages[0].Source,folder);var markerHash=SHA256.HashData(File.ReadAllBytes(Path.Combine(folder,LibraryStore.MarkerName)));var next=Relink(plan,play,lib,folder);Check(JsonSerializer.Serialize(plan)==before&&JsonSerializer.Serialize(play)==settings,"Preview mutated live data");Check(next.Packages[0].Id==plan.Packages[0].Id&&next.Packages[0].Alias=="내 게임"&&next.Packages[0].Genres.SequenceEqual(new[]{"퍼즐"}),"Metadata lost");Check(markerHash.SequenceEqual(SHA256.HashData(File.ReadAllBytes(Path.Combine(folder,LibraryStore.MarkerName)))),"Marker changed");return Done();});
await Test("reconnect-rejects-other-id",root=>{var (plan,play,lib)=Fixture(root);var folder=Path.Combine(root,"new");Directory.Move(plan.Packages[0].Source,folder);LibraryStore.EnsureIdentity(folder,Guid.NewGuid().ToString("N"));Refuse(()=>Relink(plan,play,lib,folder));return Done();});
await Test("reconnect-registered-game-needs-id",root=>{var (plan,play,lib)=Fixture(root,true);var folder=Path.Combine(root,"new");Directory.Move(plan.Packages[0].Source,folder);File.Move(Path.Combine(folder,LibraryStore.MarkerName),Path.Combine(root,"marker.saved"));Refuse(()=>Relink(plan,play,lib,folder));return Done();});
await Test("reconnect-rejects-existing-copy",root=>{var (plan,play,lib)=Fixture(root);var folder=Path.Combine(root,"copy");Directory.CreateDirectory(folder);File.WriteAllBytes(Path.Combine(folder,"Game.exe"),[1]);Refuse(()=>Relink(plan,play,lib,folder));return Done();});
await Test("reconnect-merges-only-untouched-discovered-candidate",root=>{var (plan,play,lib)=Fixture(root);var folder=Path.Combine(root,"new");Directory.Move(plan.Packages[0].Source,folder);var q=Copy(plan.Packages[0]);q.Id=Guid.NewGuid().ToString("N");q.Source=q.DetectedRoot=folder;q.Alias="";q.Genres=[];q.Registered=false;q.Name=q.Folder;plan.Packages.Add(q);var next=Relink(plan,play,lib,folder);Check(next.Packages.Count==1,"Candidate not merged");q.Alias="이미 편집한 후보";Refuse(()=>Relink(plan,play,lib,folder));return Done();});
await Test("reconnect-preserves-hidden-candidate",root=>{var (plan,play,lib)=Fixture(root);var folder=Path.Combine(root,"new");Directory.Move(plan.Packages[0].Source,folder);var q=Copy(plan.Packages[0]);q.Id=Guid.NewGuid().ToString("N");q.Source=q.DetectedRoot=folder;q.Alias="";q.Genres=[];q.Registered=false;q.Name=q.Folder;plan.Packages.Add(q);play.Games.Add(new GamePlay {Id=q.Id,Hidden=true});Refuse(()=>Relink(plan,play,lib,folder));return Done();});
await Test("explicit-reconnect-adds-new-scope-without-mutating-draft",root=>{var (plan,play,lib)=Fixture(root);var original=plan.Packages[0].Source;plan.SearchLocations=[new(){Path=original}];var folder=Path.Combine(root,"new");Directory.Move(original,folder);var next=Relink(plan,play,lib,folder);Check(next.SearchLocations!.Count==2&&next.SearchLocations.Any(l=>l.Path==folder)&&next.Packages[0].SearchRoot==folder&&plan.SearchLocations.Count==1,"Connection scope not preserved");return Done();});
await Test("reconnect-preserves-configured-candidate",root=>{var (plan,play,lib)=Fixture(root);var folder=Path.Combine(root,"new");Directory.Move(plan.Packages[0].Source,folder);var q=Copy(plan.Packages[0]);q.Id=Guid.NewGuid().ToString("N");q.Source=q.DetectedRoot=folder;q.Alias="";q.Genres=[];q.Registered=false;q.Name=q.Folder;plan.Packages.Add(q);play.Games.Add(new GamePlay {Id=q.Id,Favorite=true});Refuse(()=>Relink(plan,play,lib,folder));return Done();});
await Test("reconnect-rejects-nested-games-and-library-root",root=>{var (plan,play,lib)=Fixture(root);var folder=Path.Combine(root,"new");Directory.Move(plan.Packages[0].Source,folder);var nested=Path.Combine(folder,"other");Directory.CreateDirectory(nested);LibraryStore.EnsureIdentity(nested,Guid.NewGuid().ToString("N"));Refuse(()=>Relink(plan,play,lib,folder));Directory.CreateDirectory(plan.Destination);File.WriteAllBytes(Path.Combine(plan.Destination,"Game.exe"),[1]);Refuse(()=>Relink(plan,play,lib,plan.Destination));return Done();});
await Test("reconnect-rejects-empty-and-unreadable-folder",root=>{var (plan,play,lib)=Fixture(root);var folder=Path.Combine(root,"new");Directory.CreateDirectory(folder);Refuse(()=>Relink(plan,play,lib,folder));var scan=GameScanner.Scan(folder);scan.UnreadablePaths.Add(folder);Refuse(()=>ReconnectPlanner.Prepare(plan,plan.Packages[0].Id,folder,scan,lib,play));return Done();});
await Test("reconnect-journal-recovers-workspace-library-and-csv",root=>
{
    var (plan,play,lib)=Fixture(root,true);var folder=Path.Combine(root,"new");Directory.Move(plan.Packages[0].Source,folder);var next=Relink(plan,play,lib,folder);var tx=new EditTransaction(Path.Combine(root,"data"));tx.Checkpoint=phase=>{if(phase=="workspace")throw new IOException("Injected interruption");};
    Refuse(()=>tx.Commit(new EditBundle {Plan=next,Play=play,ReconnectedIds=[next.Packages[0].Id]}));var recovery=new EditTransaction(Path.Combine(root,"data"));Check(recovery.Recover(),"Recovery missing");var game=new LibraryStore(plan.Destination).Load().Games.Single();Check(game.LastKnownPath==folder&&game.Status=="External","Library stale");Check(File.ReadAllText(Path.Combine(plan.Destination,LibraryStore.CsvName)).Contains(folder),"CSV stale");Check(new PlayerStore(plan.Destination).Load().Games[0].Favorite,"Settings lost");return Done();
});
await Test("automatic-id-rebind-preserves-relative-launch",root=>{var (plan,play,lib)=Fixture(root,true);var folder=Path.Combine(root,"new");Directory.Move(plan.Packages[0].Source,folder);var scan=GameScanner.Scan(root);var inventory=LibraryStore.Inspect(scan);IdentityReconciler.Rebind(plan.Packages,plan.Checkpoints,lib,inventory,scan,plan.Destination);WorkspaceReconciler.Check(plan.Packages[0],plan.Checkpoints[0],scan);Check(PlayerStore.StartInfo(plan.Packages[0],play.Games[0]).FileName==Path.Combine(folder,"Game.exe"),"Relative config stale");return Done();});
await Test("organize-backup-move-edit-manual-rename-reconnect-launch",async root=>
{
    var (plan,play,lib)=Fixture(root);var p=plan.Packages[0];foreach(var file in Directory.GetFiles(AppContext.BaseDirectory))File.Copy(file,Path.Combine(p.Source,Path.GetFileName(file)),true);
    var g=play.Games[0];g.Executable=Path.GetFileName(Environment.ProcessPath!);g.Arguments="";lib=new LibraryStore(plan.Destination).Register(p,[],GameScanner.Scan(p.Source)).Document;
    var engine=new BackupEngine(Path.Combine(root,"backups"));var backup=await engine.CreateAsync(p,[]);var moved=Path.Combine(plan.Destination,p.Name);var move=await engine.MoveAsync(backup.Id,moved);Check(move.Status=="Completed","Move failed");
    var movedPlan=Relink(plan,play,lib,moved);var tx=new EditTransaction(Path.Combine(root,"data"));movedPlan.Packages[0].Alias="수정한 별칭";tx.Commit(new EditBundle {Plan=movedPlan,Play=play,EditedIds=[p.Id],ReconnectedIds=[p.Id]});
    var beforeProbe=Path.Combine(root,"before-probe.txt");g.Arguments="--probe \""+beforeProbe+"\"";using(var first=PlayerStore.Launch(movedPlan.Packages[0],g)){await first.WaitForExitAsync().WaitAsync(TimeSpan.FromSeconds(15));}Check(File.ReadAllText(beforeProbe)==moved,"Initial launch failed");new PlayerStore(plan.Destination).Save(play);
    var external=Path.Combine(root,"manual-rename");Directory.Move(moved,external);var next=Relink(movedPlan,play,new LibraryStore(plan.Destination).Load(),external);tx.Commit(new EditBundle {Plan=next,Play=play,ReconnectedIds=[p.Id]});
    var probe=Path.Combine(root,"probe.txt");g.Arguments="--probe \""+probe+"\"";using var process=PlayerStore.Launch(next.Packages[0],g);await process.WaitForExitAsync().WaitAsync(TimeSpan.FromSeconds(15));Check(File.ReadAllText(probe)==external,"Workdir wrong");Check(g.LastPlayedUtc!=null&&next.Packages[0].Alias=="수정한 별칭","State lost");Check(Directory.Exists(engine.Payload(backup)),"Backup missing");
});
File.WriteAllText(Path.GetFullPath(args[1]),JsonSerializer.Serialize(new{runRoot=run,total=results.Count,passed=results.Count-failed,failed,results},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"RESULT: {results.Count-failed}/{results.Count}");Environment.ExitCode=failed==0?0:1;
